        "A kiválasztott nyelven nem érhető el beszédfelismerés. Állítsd be az Androidon." to listOf("Spracherkennung ist in dieser Sprache nicht verfügbar. Prüfe die Android-Einstellungen.", "La reconnaissance vocale n'est pas disponible dans cette langue. Vérifiez Android.", "El reconocimiento de voz no está disponible en este idioma. Comprueba Android.", "Il riconoscimento vocale non è disponibile in questa lingua. Controlla Android.", "Rozpoznawanie mowy nie jest dostępne w tym języku. Sprawdź ustawienia Androida."),
    )
    private val languages = listOf(
        JarvisLanguage.GERMAN, JarvisLanguage.FRENCH,
        JarvisLanguage.SPANISH, JarvisLanguage.ITALIAN, JarvisLanguage.POLISH
    )
    private val prefixes = mapOf(
        "Állapot: " to listOf("Status: ", "État : ", "Estado: ", "Stato: ", "Stan: "),
        "Hallottam: " to listOf("Gehört: ", "Entendu : ", "Escuché: ", "Ho sentito: ", "Usłyszano: "),
        "Hossz: " to listOf("Dauer: ", "Durée : ", "Duración: ", "Durata: ", "Czas: "),
        "Videó áttekintése: " to listOf("Videovorschau: ", "Aperçu vidéo : ", "Vista previa: ", "Anteprima video: ", "Podgląd wideo: "),
        "Jelenleg mentett kapcsolat: " to listOf("Gespeicherte Verbindung: ", "Connexion enregistrée : ", "Conexión guardada: ", "Connessione salvata: ", "Zapisane połączenie: "),
        "Átlag: " to listOf("Durchschnitt: ", "Moyenne : ", "Promedio: ", "Media: ", "Średnia: "),
        "Helyben kinyert képkockák: " to listOf("Lokal extrahierte Bilder: ", "Images extraites localement : ", "Fotogramas extraídos: ", "Fotogrammi estratti: ", "Lokalnie wyodrębnione klatki: "),
    )
    fun text(original: String, language: JarvisLanguage): String? {
        val ix = languages.indexOf(language)
        if (ix < 0) return null
        five[original]?.let { return it[ix] }
        return prefixes.entries.firstOrNull { original.startsWith(it.key) }
            ?.let { it.value[ix] + original.removePrefix(it.key) }
    }
}
